import { createContext, useState } from 'react';

const FeedbackContext = createContext();

const FeedbackProvider = ({ children }) => {
  const [feedback, setFeedback] = useState({
    questions: [
      { id: 1, text: 'What did you think of the lecture?' },
      { id: 2, text: 'What did you find most interesting?' },
      { id: 3, text: 'What did you find most challenging?' },
    ],
    answers: [],
  });

  const addAnswer = (id, answer) => {
    setFeedback((prevFeedback) => ({
      ...prevFeedback,
      answers: [...prevFeedback.answers, { questionId: id, answer }],
    }));
  };

  return (
    <FeedbackContext.Provider value={{ feedback, addAnswer }}>
      {children}
    </FeedbackContext.Provider>
  );
};

